WHEN MATCHED THEN
    UPDATE SET
        tgt.Nombre = src.Nombre,
        tgt.DefinicionUrl = src.DefinicionUrl
WHEN NOT MATCHED BY TARGET THEN
    INSERT (Codigo, Nombre, DefinicionUrl)
    VALUES (src.Codigo, src.Nombre, src.DefinicionUrl);
COMMIT;
